  const uint64_t modifiers = 0;
  amdgpu::arith::execute_integer16<1>(wf, rj_arith_v_not_b16_w32, rj_arith_v_not_b16_w64,
                                      wf.cu().arithmetic_flags(), modifiers, vdst, src0);
